def merge_intervals(intervals):
    """Merge overlapping [start, end] intervals. Returns a new sorted list."""
    if not intervals:
        return []
    intervals.sort(key=lambda x: x[0])
    out = [intervals[0]]
    for start, end in intervals[1:]:
        last = out[-1]
        if start < last[1]:
            last[1] = max(last[1], end)
        else:
            out.append([start, end])
    return out

